const records = [];

for (const item of $input.all()) {
  records.push(item.json);
}

const jsonEachRowString = records.map(row => JSON.stringify(row)).join('\n');

return {
  json: {
    formatted_data: jsonEachRowString
  }
};

const daysToSubtract = 30;

for (const item of $input.all()) {
  const originalDate = new Date(item.json.start_date);
  originalDate.setDate(originalDate.getDate() - daysToSubtract);
  item.json.data_start_date = originalDate.toISOString().split('T')[0];
}

return $input.all();

const payload = $input.first().json;

const startDate = payload.start_date;
const endDate = payload.end_date;
const indicesArr = payload.data || [];

return indicesArr.map(item => ({
  json: {
    index_id: item.index_id,
    start_date: startDate,
    end_date: endDate
  }
}));

let indicesArr = [];
let indicesStr = "";
for (const item of $input.all()) {
  indicesArr.push(item.json["index_id"]);
  indicesStr = indicesArr.map(x => "'" + x + "'").join(",");
}

const startDate = items[0].json.start_date;
const endDate = items[0].json.end_date;

return [{ 
  start_date: startDate,
  end_date: endDate,
  index_ids: indicesArr,
  index_id_str: indicesStr 
}];

// Extract rows array from ClickHouse JSON wrapper ($input.first().json.data)
let inputData = $input.first()?.json?.data || [];

const uniqueMap = new Map();
for (const item of inputData) {
  const key = `${item.index_id}_${item.time}`;
  if (!uniqueMap.has(key)) {
    uniqueMap.set(key, item);
  }
}
const inputDataCleaned = Array.from(uniqueMap.values());
inputData = inputDataCleaned;

// Group items by index_id
const groupedData = {};
for (const item of inputData) {
  const indexId = item.index_id;
  if (!groupedData[indexId]) {
    groupedData[indexId] = [];
  }
  groupedData[indexId].push(item);
}

const outputItems = [];

// Process each stock group
for (const index in groupedData) {
  const indexItems = groupedData[index].sort(
    (a, b) => new Date(a.time) - new Date(b.time)
  );

  let prevItem = null;
  for (let i = 0; i < indexItems.length; i++) {
    const currentItem = indexItems[i];
    const n = (i >= 4) ? i-4 : 0;

    if (Number(currentItem.window_padding) === 0) {
      const netBreadth = currentItem.advances - currentItem.declines;
      const breadthRatio = netBreadth / (currentItem.advances + currentItem.declines);

      if (prevItem != null) {
        outputItems.push({
          json: {
            index_id: currentItem.index_id,
            time: currentItem.time,
            net_breadth:netBreadth,
            cumulative_ad: prevItem.cumulativeAd + netBreadth,
            breadth_ratio: breadthRatio,
            ad_slope: netBreadth, 
            ad_slope_5: (prevItem.cumulativeAd + netBreadth - indexItems[n]) / 5
          }
        });
        currentItem.cumulativeAd = prevItem.cumulativeAd + netBreadth;
      } else {
        // Start cell
         outputItems.push({
          json: {
            index_id: currentItem.index_id,
            time: currentItem.time,
            net_breadth: netBreadth,
            cumulative_ad: netBreadth,
            breadth_ratio: breadthRatio,
            ad_slope: 0,
            ad_slope_5: 0
          }
        }); 
        currentItem.cumulativeAd = netBreadth
      }
    }

    prevItem = currentItem;
  }
}

return outputItems;
